{
  "company": "CRONUS International Ltd.",
  "messageType": "Inventory.TransferOrder.Post",
  "status": "Success",
  "contract": "json",
  "format": "chapters",
  "catalogue": {
    "name": "Inventory.TransferOrder.Post",
    "isEnabled": true,
    "filterTableNo": 5740,
    "description": "Posts a transfer order (ship/receive, or ship+receive for direct transfers).",
    "selectionDescription": "Posts a transfer order by shipping or receiving it; use PreviewPost to inspect predicted entries first.",
    "messageDirection": "Inbound",
    "keywords": [
      "post transfer",
      "ship transfer order",
      "receive transfer order",
      "goods arrived at the other warehouse",
      "direct transfer"
    ],
    "chargeable": true
  },
  "chapters": {
    "envelope": {
      "subject": {
        "use": "optional",
        "forms": [
          "guid",
          "document no."
        ],
        "description": "The subject identifies the transfer order by number or SystemId; use data document identifiers when subject is omitted."
      },
      "dataRequired": true,
      "version": "1.0",
      "contentType": "text/json"
    },
    "target": [
      {
        "source": "subject",
        "form": "guid",
        "description": "The SystemId of the document header."
      },
      {
        "source": "subject",
        "form": "document no.",
        "description": "The No. of the document header."
      },
      {
        "source": "data.systemId, data.recordSystemId, data.id",
        "form": "guid",
        "description": "The SystemId of the document header."
      },
      {
        "source": "data.documentNo, data.transferOrderNo, data.no",
        "form": "document no.",
        "description": "The Transfer Order No."
      }
    ],
    "parameters": [
      {
        "name": "postingType",
        "type": "string",
        "required": false,
        "description": "Ship or Receive. Required for a non-direct transfer; ignored for a direct transfer. ShipReceive is refused."
      }
    ],
    "response": {
      "contentType": "text/json",
      "fields": [
        {
          "name": "status",
          "type": "string",
          "description": "Success when posting completed."
        },
        {
          "name": "documentNo",
          "type": "string",
          "description": "The original Transfer Order No."
        },
        {
          "name": "postingType",
          "type": "string",
          "description": "Ship, Receive or DirectTransfer."
        },
        {
          "name": "directTransfer",
          "type": "boolean",
          "description": "Whether the order was direct."
        },
        {
          "name": "postedShipmentNo",
          "type": "string",
          "description": "Posted shipment number when one was created (the direct transfer number for a direct transfer)."
        },
        {
          "name": "postedReceiptNo",
          "type": "string",
          "description": "Posted receipt number when one was created (the direct transfer number for a direct transfer)."
        },
        {
          "name": "orderDeleted",
          "type": "boolean",
          "description": "True when the posting completed the order and Business Central deleted it (a full receive or a direct transfer)."
        },
        {
          "name": "postingDate",
          "type": "string",
          "description": "Posting date in YYYY-MM-DD format."
        }
      ]
    },
    "errors": [
      {
        "code": "MissingParameter",
        "when": "No Transfer Header identifier in subject or data. A non-direct transfer order also requires postingType.",
        "fix": "Send subject or an identifier key under data. For a non-direct transfer, send postingType Ship or Receive."
      },
      {
        "code": "RecordNotFound",
        "when": "An identifier was given but matches no Transfer Header.",
        "fix": "Check the value or look the record up first."
      },
      {
        "code": "ConflictingIdentifiers",
        "when": "Two identifiers were given that point to different records.",
        "fix": "Send one identifier."
      },
      {
        "code": "InvalidParameterFormat",
        "when": "data is not a JSON object (parameter data); an identifier key under data (documentNo, transferOrderNo, no, systemId, recordSystemId, id) is not a JSON string (null, a number, a boolean, an object or an array); or a SystemId is not a GUID. parameter names the key.",
        "fix": "Send data as a JSON object, each identifier as a JSON string and a SystemId as a GUID. Nothing is looked up while one is wrong."
      },
      {
        "code": "MultipleErrors",
        "when": "More than one identifier key is of the wrong type; errors[] lists each, in the order the keys are read. Nothing is looked up while one is wrong.",
        "fix": "Fix every listed key and send the request again."
      },
      {
        "code": "InvalidParameter",
        "error": "postingType must be \"Ship\", \"Receive\", or \"ShipReceive\". Received: %1",
        "when": "postingType is not Ship or Receive. ShipReceive is named in the text but is refused as well.",
        "fix": "Send Ship or Receive in two separate calls."
      },
      {
        "code": "BusinessCentralError",
        "error": "Business Central's own posting error text.",
        "when": "Business Central refused the posting, for example because the order is not ready to ship or receive.",
        "fix": "Read the error text and correct the order or setup."
      },
      {
        "code": "InvalidParameter",
        "error": "The Transfer Orders domain is turned off for this company. Turn it on from Inventory Setup.",
        "when": "The Transfer Orders domain is turned off on the Inventory Setup page.",
        "fix": "Turn the domain on from the Inventory Setup page."
      },
      {
        "code": "PermissionDenied",
        "error": "Permission denied for this inventory message type.",
        "when": "The domain is on, but the caller lacks Inv. Posting Gate, which posting requires in addition to the Bifrost \"Full Access\" permission set.",
        "fix": "Assign the missing permission set to the caller."
      }
    ],
    "effect": {
      "effect": "irreversible",
      "changes": "Posts the Transfer Order as a shipment, a receipt or a direct transfer: creates the posted transfer shipment, receipt or direct transfer document with its item ledger and value entries, and updates or deletes the order. The call commits and ignores Omit Commit; the posting cannot be rolled back afterwards.",
      "idempotent": false,
      "permissionSet": "the Bifrost \"Full Access\" permission set and Inv. Posting Gate",
      "preconditions": [
        "The Transfer Orders domain is turned on in Inventory Setup.",
        "The caller holds Inv. Posting Gate in addition to the Bifrost \"Full Access\" permission set.",
        "The order has lines and is ready to be shipped or received."
      ]
    },
    "metering": {
      "chargeable": true,
      "chargedAs": "message"
    },
    "related": [
      {
        "name": "Inventory.TransferOrder.PreviewPost",
        "useInsteadWhen": "Preview the posting without committing."
      },
      {
        "name": "Inventory.TransferOrder.Release",
        "useInsteadWhen": "Release before posting."
      }
    ],
    "workflow": {
      "steps": [
        {
          "messageType": "Inventory.TransferOrder.Statistics",
          "purpose": "Check quantities and totals."
        },
        {
          "messageType": "Inventory.TransferOrder.PreviewPost",
          "purpose": "Preview the posting."
        },
        {
          "messageType": "Inventory.TransferOrder.Post",
          "purpose": "Post with postingType Ship, then again with Receive."
        }
      ]
    },
    "examples": [
      {
        "title": "Ship a released transfer order",
        "request": {
          "type": "Inventory.TransferOrder.Post",
          "data": {
            "documentNo": "TO000456",
            "postingType": "Ship"
          }
        },
        "response": {
          "status": "Success",
          "documentNo": "TO000456",
          "postingType": "Ship",
          "directTransfer": false,
          "postedShipmentNo": "109001",
          "postedReceiptNo": "",
          "orderDeleted": false,
          "postingDate": "2026-10-22"
        }
      }
    ],
    "overview": "Posts a Transfer Order as Ship, Receive or direct transfer and writes the corresponding inventory documents and ledger entries.",
    "notes": "Non-direct orders require postingType Ship or Receive; ShipReceive is refused. Direct transfers ignore postingType and use the Inventory Setup direct-transfer posting configuration. A Receive that receives the last quantity deletes the transfer order; the response is still Success with postedReceiptNo and orderDeleted true. The call commits: it commits the transaction before posting starts, Business Central's own posting commits as well, and Omit Commit is not honoured, so a successful posting cannot be rolled back. It requires Inv. Posting Gate in addition to the Bifrost \"Full Access\" permission set. Use Inventory.TransferOrder.PreviewPost first to see the entries."
  },
  "conventions": "## Errors and warnings\r\nAn error response has `status` = `Error`, a stable `code`, the `error` text and, when they apply, `parameter` (the request parameter concerned, e.g. `lines[2].no`), `received` (the value received), `expected` (what was expected) and `nextStep` (what to do now). `hint` says where to read more.\r\nWhen a request has several problems, all of them are listed in `errors[]` - each with the same fields - under a top-level `code` (`MultipleErrors`, or a shared code such as `InvalidLine` for the `lines` of a Create type) and a summary `error`. Fix them all before calling again. One problem is reported at the top level, with no `errors[]`.\r\nRequest values are checked first and every problem found is reported together. A Business Central validation error raised afterwards, while a record is being written, stops the call and is reported on its own: `code` = `BusinessCentralError`, Business Central's own `error` text, and `parameter` naming the request parameter being applied, e.g. `lines[1].accountNo`. Nothing is written.\r\nRequest values are read in one format, whatever the language: dates `YYYY-MM-DD`; date-times ISO 8601 with `Z` or an offset; amounts as JSON numbers (or a string such as `\"1234.56\"`, no thousands separator); integers as JSON integers; booleans `true` or `false`. Any other value is `InvalidParameterFormat` with `received` and `expected`; for an unambiguous local form such as `26.09.2026`, `nextStep` gives the value to resend. Every bad value of a request is reported together.\r\nAnswers are written in one format as well, whatever the language of the call: dates `YYYY-MM-DD`, date-times ISO 8601, numbers with a dot and no thousands separator, and the option and enum values of every answer except `Data.Records.Get` and `Data.Records.Set` as their English names, so a value read from an answer can be sent back. Those two answer the caption of the language of the call, for a person to read. The language of the call (`lcid`) changes captions and message texts, not these forms. Two things are outside Bifrost's control: Business Central writes its own texts (a ledger entry description such as `Direct Cost V00010 on 10/02/26`, the text of a `BusinessCentralError`) with the regional settings of the server session, which `lcid` does not change, so a date in such a text can be in month-day order; and a table view is read with those settings too, so write dates in a view as `YYYY-MM-DD` and decimals with a dot.\r\nBoth success and error responses can carry `warnings[]`, each with `code`, `message` and, when they apply, `parameter` and `nextStep`.\r\n`UnknownParameter` refuses undeclared data keys before execution for every type whose effect is not read, including a missing effect. The root envelope option `strict:false` cannot opt out. Read types keep warnings without changing status, validationResult or domain warningCount unless the caller sets `strict:true` (next to type and subject, never inside data). Refusals list the keys and localized nextStep corrections; no business changes or successful execution charges occur. Example: {\"type\":\"Memory.User.Set\",\"strict\":true,\"data\":{\"memory\":\"test\",\"memry\":\"typo\"}} is refused.\r\n`FieldChangedByBC` is a warning from Data.Records.Set: another field validation or the write changed a sent field after its own validation. `parameter` names data[n].fields.{jsonName}, counting from 0. Status stays Success. Compare the returned values with what you sent; follow `nextStep` to use validation order or send the field again in a separate call. Normalisation of the field itself, LCY, Dimension Set ID, BLOB, Media, MediaSet and skipped fields are excluded.\r\nFeature apps (Foundation 28.0.8 or later) can call `Argument.SetErrorContext(Parameter, Expected, NextStep)` before an operation that may fail after writes, then `Argument.ClearErrorContext()` after success. Supply the parameter name and translated labels, never request values, file content, credentials or a call stack. Foundation returns that context on the original `BusinessCentralError` after rollback, including uncaught task errors; `RespondWithLastError()` also uses it. The API does not catch errors, commit data or change the transaction boundary. Keep no-return `Codeunit.Run` and let errors propagate for chained `OmitCommit` calls; never add a Boolean `Codeunit.Run` or a writing `TryFunction` to recover context. Context is cleared between messages. Existing callers without context keep their response shape; recognized lock errors keep their existing `Retryable` guidance.\r\nA message type that must run only one way (Foundation 28.0.9 or later) reads `Argument.GetInvocationSource()`: `Queue` when the task scheduler runs a message the queue API scheduled, `Task` for the Task API (`/tasks`), `Dispatcher` for an internal call through `Dispatcher ori` (the in-product MCP tool server, a nested dispatch from another message type), `Direct` for the Messages page Run Task action and anything unset. Only Foundation sets it; request values, parameters, source, subject and writes to the argument cannot change it. Refuse the other paths with `PreconditionFailed` and a `nextStep` that names the path to use.\r\n`Retryable` means a transient lock or deadlock caught while writing or posting. `error` keeps Business Central's original text. `expected` is \"no concurrent lock on the same records\"; `nextStep` is \"Retry the same call after a few seconds; nothing was changed.\" Bifrost does not retry automatically. Other platform errors, including uncaught queue-path errors, remain `BusinessCentralError`.\r\nCodes: `MissingParameter`, `InvalidParameterFormat`, `InvalidParameter`, `RecordNotFound`, `AmbiguousRecord`, `ConflictingIdentifiers`, `InvalidFilterField`, `InvalidLine`, `NothingToPreview`, `LinesSkipped`, `BlockedByWriteGuard`, `PreconditionFailed`, `PermissionDenied`, `LimitExceeded`, `BusinessCentralError`, `MultipleErrors`, `DeprecatedParameter`, `UnknownParameter`, `FieldChangedByBC`, `Retryable`, `EULA_REQUIRED`, `TRIAL_NOT_STARTED`. The `error` text may be translated; the code never is.\r\n"
}
